#!/usr/bin/env bash
# 往復証跡（PR コメント）の形式・往復上限を検査する（Issue #25）。
#
# review-trail.yml から呼ばれるプロセス検査の本体。PR コメント（TRAIL_FILE に連結済み）に、
# 実装↔レビューの往復が verification-loop.md「実装↔レビューループ」の定型フォーマットで
# 記録されているか、往復数が「ループの上限値」表の上限内かを機械的に確認する。
#
# 【なぜコメントで、本文でないか】
#   証跡の置き場所を PR コメントと定めているのは verification-loop.md「実装↔レビューループ」。
#   往復ごとに追記され、その順序自体が経緯の記録になる（本文編集では履歴が残らない）。
#   検査対象を docs の定義とずらさないこと。ずれると「docs どおりに書くと落ちる」になる。
#
# 【この検査の限界 ― 記録しか見ない】
#   見るのは *PR に記録された* 往復ブロックの形式と往復数であって、実セッションの
#   実装↔レビュー往復そのものではない。記録をごまかせば擦り抜ける（外部が書き込める
#   場所を正解にしない、という ADR 0004 と同じ留意）。指摘レベルの分類（Critical/
#   Warning/Info の妥当性）と2段承認ゲートの成立は artifact に残らず、検査できない。
#   コードフェンス内に貼られた整形済みブロックも往復として数える（同じ「ごまかせば
#   擦り抜ける」の範囲内）。なお本スクリプトの失敗メッセージをそのまま貼っても
#   誤爆はしない ― テンプレートの `N` が数字でないため往復見出しに一致しない。
#
# 【信頼境界 ― 検査対象は第三者が書き込める場所である】
#   PR 本文は著者とメンテナしか編集できないが、PR コメントは *コメント権限のある
#   第三者なら誰でも追記できる*。上の「記録をごまかせる」は当事者の話だが、こちらは
#   別軸で、第三者が必須5行そろいの『### 往復 99』を1つ投稿するだけで必須チェックを
#   恒久的に赤にできる（復旧手段はコメント削除のみ）。逆に整形済みブロックを
#   投稿して通すこともできる。証跡としての性質上この置き場所を選んでいるが
#   （verification-loop.md「実装↔レビューループ」）、限界として明記する。
#
# 入力:
#   TRAIL_FILE        … PR コメントを連結したファイルのパス（review-trail.yml が gh api で作る）。
#                       コメント本文は外部からの入力なので、シェルに展開せずファイル経由で渡す。
#   REVIEW_LOOP_DOC   … 上限値の単一情報源（既定 docs/harness/verification-loop.md）
#   HAS_LOOP_EXTENDED … loop-extended ラベルの有無（"true" で上限超過を許容）
#
# 【loop-extended ラベルが要る理由】
#   上限超過の扱いは「握り潰さず人間へ上げる」であって「常に禁止」ではない。人間が
#   延長を承認することはある。だがその承認は session 内の判断で artifact に残らず、
#   機械には「承認された延長」と「握り潰し」の区別が付かない（ADR 0010 §F の
#   止められない側 / Issue #25 でスコープ外とした2段承認ゲート）。
#   そこで no-spec と同じ形をとる ―― **例外にラベルという明示的な操作を要求し、
#   例外を使った事実を記録に残す。** ラベルで免除するのは上限だけで、形式は免除しない。
set -euo pipefail

TRAIL_FILE="${TRAIL_FILE:-}"
if [ -z "$TRAIL_FILE" ] || [ ! -f "$TRAIL_FILE" ]; then
  echo "NG: 往復証跡の入力（TRAIL_FILE）が渡されていない。review-trail.yml の取得ステップを確認すること。"
  exit 1
fi

DOC="${REVIEW_LOOP_DOC:-docs/harness/verification-loop.md}"

# --- 上限値を単一情報源（verification-loop.md「ループの上限値」表）から読む ---------
# スクリプトにハードコードしない（Issue #25 / ADR 0010 §A の閾値は人間の承認事項）。
# 読み取れなければ「単一情報源の書式が動いた」合図として fail する。黙って素通りさせない。
#
# マークダウン表のセル（行頭 `| 実装↔レビューの往復 |`）にアンカーする。行内一致だと
# 「実装↔レビューの往復…」を含む散文行にも当たり、将来そこへ太字数字が書かれると
# head -n1 が誤値を黙って拾う（＝単一情報源を検査自身が壊す）。表の行に限定して防ぐ。
cap="$(grep -E '^\|[[:space:]]*実装↔レビューの往復[[:space:]]*\|' "$DOC" \
  | grep -oE '\*\*[0-9]+\*\*' \
  | grep -oE '[0-9]+' \
  | head -n1 || true)"

if [ -z "${cap:-}" ]; then
  echo "NG: 往復上限を $DOC「ループの上限値」から読み取れなかった。"
  echo "    行『実装↔レビューの往復 | **N** | ...』が見つからない。表の書式が変わった可能性。"
  echo "    上限はスクリプトにハードコードせず単一情報源から読む方針（Issue #25）。"
  exit 1
fi

# --- PR コメントの往復ブロックを検証 -----------------------------------------------
# CRLF を落として awk へ。ラベルは前後の空白に寛容に一致させる（整形のブレを許す）。
if tr -d '\r' < "$TRAIL_FILE" | awk -v cap="$cap" -v extended="${HAS_LOOP_EXTENDED:-false}" '
  function flush(   miss) {
    if (!in_block) return
    miss=""
    if (!has_c)   miss = miss " Critical"
    if (!has_w)   miss = miss " Warning"
    if (!has_i)   miss = miss " Info"
    if (!has_r)   miss = miss " 対応"
    if (!has_u)   miss = miss " 未解決"
    if (miss != "") {
      msgs = msgs sprintf("  往復 %d: 必須行が欠けている →%s\n", curn, miss)
      bad = 1
    }
  }
  # 往復見出しは *任意の見出しレベル* で拾う。`###` ちょうどに限定すると、
  # `## 往復 4` / `#### 往復 4` / `###往復 4` が下の汎用見出しルールに吸われて
  # next で捨てられ、往復が「存在しないもの」になる。`#` を1つ打ち間違えるだけで
  # 上限超過が OK で通った（実測）。検査対象を読めなかったこと・読み損ねたことを
  # 「違反が無いこと」の意味にしない（verification-loop.md）。
  #
  # 拾ったうえで、定型『### 往復 N』でないものは無視せず NG にする。
  #
  # ただし *数字で行が終わる* ものに限る（末尾は空白のみ許す）。行末を要求しないと
  # 「往復 N」を含む見出しなら何でも往復ブロック扱いになり、
  # `#### 往復 1 の指摘への回答` / `## 往復2回目のレビューまとめ` のような
  # *このリポジトリのエージェントが日本語で自然に書く見出し* が必須5行欠落として
  # 恒久的に赤くなる（復旧手段はコメント編集のみ／実測）。docs どおりに書いて落ちる
  # 検査にしない、が優先する。
  #
  # 【トレードオフ】この限定で `### 往復 4 — 補足` のような後置き文字列は
  #   ブロックとして数えられず、上限超過をすり抜けうる。これは意図的な選択である:
  #     - 見出しレベルの取りこぼし（C-1）は `#` の打ち間違いという *事故* で起き、
  #       上限超過という停止条件を黙って緑にする。ここは一切緩めていない
  #       （`#+` のまま。`## 往復 4` は今も NG）。
  #     - 後置き文字列での回避は「定型で書かない」という *意図的な逸脱* であり、
  #       この検査がもともと明記している「記録をごまかせば擦り抜ける」の範囲内。
  #   事故で誤爆する面だけを狭め、事故で見逃す面は狭めていない。
  /^[ \t]*#+[ \t]*往復[ \t]*[0-9]+[ \t]*(—|–|：|（|\(|:|-|$)/ {
    flush()
    in_block = 1; count++
    s = $0
    sub(/^[ \t]*#+[ \t]*往復[ \t]*/, "", s); sub(/[^0-9].*/, "", s)
    curn = s + 0
    if (curn > maxn) maxn = curn
    # 見出しレベル・区切り空白が定型どおりか。ずれていたら落とす（黙殺しない）。
    if ($0 !~ /^[ \t]*###[ \t]+往復[ \t]+[0-9]+/) {
      msgs = msgs sprintf("  往復 %d: 見出しが定型『### 往復 N』でない → %s\n", curn, $0)
      bad = 1
    }
    has_c = has_w = has_i = has_r = has_u = 0
    next
  }
  # 往復以外の見出しでブロックを閉じる。閉じないと、別章やコメント境界をまたいだ
  # 「- 未解決 :」を直前の往復のものとして数え、欠落を見逃す（検査が甘くなる）。
  #
  # 見出しは `#+` で書く。`#{1,6}` の区間指定は mawk（GitHub runner の既定 awk）が
  # 解釈せず、条件が常に偽になって修正が無効化される。gawk では通るため気づきにくい。
  #
  # `#` の直後の空白を要求しない。要求すると `###補足` がブロックを閉じず、後続の
  # `- 対応` / `- 未解決` が直前の往復に計上されて欠落を見逃す（＝検査が甘くなる）。
  # 上の往復見出し側が `###往復 4` を拾うのと向きをそろえる。GFM では見出しでないが、
  # 行頭 `#` は見出しとみなす（どちらの側も安全側＝厳しい側に倒す）。
  /^[ \t]*#+/ {
    flush()
    in_block = 0
    next
  }
  in_block {
    if ($0 ~ /^[ \t]*[-*][ \t]*Critical[ \t]*:/)  has_c = 1
    else if ($0 ~ /^[ \t]*[-*][ \t]*Warning[ \t]*:/)  has_w = 1
    else if ($0 ~ /^[ \t]*[-*][ \t]*Info[ \t]*:/)     has_i = 1
    else if ($0 ~ /^[ \t]*[-*][ \t]*対応[ \t]*:/)     has_r = 1
    else if ($0 ~ /^[ \t]*[-*][ \t]*未解決[ \t]*:/)   has_u = 1
  }
  END {
    flush()
    if (count == 0) {
      msgs = msgs "  『### 往復 N』ブロックが PR コメントに1つも無い\n"
      bad = 1
    }
    # 上限超過は既定で fail。ただし loop-extended ラベルが付いていれば、
    # 人間が延長を承認した事実が記録に残っているものとして通す（下の注記も参照）。
    # 形式（必須5行・ブロックの存在）はラベルでは免除しない。緩めるのは上限だけ。
    if (maxn > cap) {
      if (extended == "true") {
        exceeded = 1
      } else {
        msgs = msgs sprintf("  往復 %d が上限 %d を超えている（収束せず＝握り潰さず人間へ上げる状況）\n", maxn, cap)
        msgs = msgs "  人間が延長を承認したのなら loop-extended ラベルを付けること（承認を記録に残すため）。\n"
        bad = 1
      }
    }
    if (bad) {
      printf("NG: 往復証跡（PR コメント）の形式・往復数が要件を満たさない\n")
      printf("%s", msgs)
      exit 1
    }
    if (exceeded) {
      # 例外を使った事実は必ず出力に残す。黙って緑にしない。
      printf("OK（例外）: 往復ブロック %d 個 / 最大 往復 %d > 上限 %d\n", count, maxn, cap)
      printf("  loop-extended ラベルによる人間承認済みの延長として通した。各ブロックに必須5行そろい。\n")
      exit 0
    }
    printf("OK: 往復ブロック %d 個 / 最大 往復 %d ≤ 上限 %d / 各ブロックに必須5行そろい\n", count, maxn, cap)
  }
'; then
  exit 0
fi

echo ""
echo "  往復ごとに次のフォーマットで PR にコメントを残すこと（verification-loop.md「実装↔レビューループ」）:"
echo ""
echo "    ### 往復 N"
echo "    - Critical: <件数> — <要点。無ければ「なし」>"
echo "    - Warning : <件数> — <要点。無ければ「なし」>"
echo "    - Info    : <件数> — <要点。無ければ「なし」>"
echo "    - 対応    : <この往復で implementer が直した点>"
echo "    - 未解決  : <次往復へ持ち越す点。無ければ「なし」>"
echo ""
echo "  往復が上限を超えたら握り潰さず人間へ上げる（verification-loop.md「停止条件」）。"
echo "  仕様を要さない変更なら no-spec ラベルを付けること。"
exit 1
